text(await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
p = Path('.local/hermes-lab/receive-slack-tokens.py')
p.write_text('''from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.parse import parse_qs
import json, os, re, secrets, threading

root = Path(__file__).parent
path = root / "home" / ".env"
if path.read_text().strip():
    raise SystemExit("Refusing to overwrite nonempty lab credentials.")
route = "/" + secrets.token_hex(24)

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass
    def respond(self, status, body):
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Security-Policy", "default-src 'none'; form-action 'self'; frame-ancestors 'none'")
        self.end_headers()
        self.wfile.write(body.encode())
    def allowed(self):
        return self.path == route and self.headers.get("Host") == f"127.0.0.1:{self.server.server_port}"
    def do_GET(self):
        if not self.allowed():
            return self.respond(404, "Not found")
        self.respond(200, '<!doctype html><title>clanker local credential save</title><h1>Save Slack tokens locally</h1><p>This one-time local form writes only to the approved clanker lab .env. It stops after saving.</p><form method="post" autocomplete="off"><p><label>Slack bot token <input name="bot" type="password" autocomplete="off" required></label></p><p><label>Slack app token <input name="app" type="password" autocomplete="off" required></label></p><button>Save to local lab</button></form>')
    def do_POST(self):
        expected_origin = f"http://127.0.0.1:{self.server.server_port}"
        if not self.allowed() or self.headers.get("Origin") != expected_origin:
            return self.respond(403, "Denied")
        size = int(self.headers.get("Content-Length", "0"))
        if size <= 0 or size > 4096:
            return self.respond(400, "Invalid request")
        data = parse_qs(self.rfile.read(size).decode())
        bot = data.get("bot", [""])[0]
        app = data.get("app", [""])[0]
        if not re.fullmatch(r"xoxb-[A-Za-z0-9-]+", bot) or not re.fullmatch(r"xapp-[A-Za-z0-9-]+", app):
            return self.respond(400, "Token format rejected; nothing saved.")
        if path.read_text().strip():
            return self.respond(409, "Credentials already present; nothing overwritten.")
        fd = os.open(path, os.O_WRONLY | os.O_TRUNC, 0o600)
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "w") as out:
            out.write(f"SLACK_BOT_TOKEN={bot}\\nSLACK_APP_TOKEN={app}\\nSLACK_ALLOWED_USERS=OWNER_ID_PENDING\\n")
        self.respond(200, "<!doctype html><title>clanker tokens saved</title><h1>Tokens saved locally</h1><p>Both Slack tokens were saved to the approved lab .env with owner-only permissions. This receiver is now stopped.</p>")
        print("SAVED: both Slack tokens; file mode 600; no token values logged.", flush=True)
        threading.Thread(target=self.server.shutdown, daemon=True).start()

server = HTTPServer(("127.0.0.1", 0), Handler)
print(json.dumps({"url": f"http://127.0.0.1:{server.server_port}{route}"}), flush=True)
server.serve_forever()
server.server_close()
''')
p.chmod(0o700)
